/* Rust translation of sb1250_dma.h.  Definitions from sb1250_defs.h are external. */

/* The following helper macros correspond to the C header's field-value macros. */
macro_rules! _SB_MAKE64 { ($x:expr) => { $x as u64 }; }
macro_rules! _SB_MAKEMASK1 { ($x:expr) => { 1u64 << ($x as u32) }; }
macro_rules! _SB_MAKEMASK { ($n:expr, $s:expr) => { (((1u64 << ($n as u32)) - 1) << ($s as u32)) }; }
macro_rules! _SB_MAKEVALUE { ($x:expr, $s:expr) => { (($x as u64) << ($s as u32)) }; }
macro_rules! _SB_GETVALUE { ($x:expr, $s:expr, $m:expr) => { (($x as u64 & $m) >> ($s as u32)) }; }

macro_rules! field_value { ($name:ident, $s:ident) => { macro_rules! $name { ($x:expr) => { _SB_MAKEVALUE!($x, $s) }; } }; }
macro_rules! field_get { ($name:ident, $s:ident, $m:ident) => { macro_rules! $name { ($x:expr) => { _SB_GETVALUE!($x, $s, $m) }; } }; }

